#include <map>
#include <iostream>

// Stateful Comparator Example
struct MyCompare {
    bool reverse_order = false;
    bool operator()(int a, int b) const {
        return reverse_order ? (a > b) : (a < b);
    }
};

int main() {
    std::map<int, int, MyCompare> m1;
    m1.key_comp().reverse_order = true; // Set state
    m1[1] = 1; m1[5] = 5; 

    std::map<int, int, MyCompare> m2;
    m2 = m1; // Assignment copies elements AND comparator state

    // m2 now also uses reverse_order = true
    std::cout << "m2 reverse state: " 
              << m2.key_comp().reverse_order << "\n"; 
}
